			const costs = [];
			for (let h = 0; h < 24; h++) costs.push(getBucket(h).cost);
			const maxCost = costs.reduce((m, c) => Math.max(m, c), 0);
			const levelOf = (c) => (c <= 0 ? 0 : Math.min(4, 1 + Math.floor((c / maxCost) * 3)));
			const cells = [];
			for (let h = 0; h < 24; h++) {
				const b = getBucket(h);
