		const SESS_RADIUS = 5.5;
		const SESS_CIRCUMFERENCE = 2 * Math.PI * SESS_RADIUS;
		/** 时段 → 面板条/图例色（tint 类名对齐官方 ContextMeter 的三色 + 暖色） */
		const SESS_BAND_TINT = {
			before: 'usg-sess-tint-system',
			afterPeak: 'usg-sess-tint-messages',
			afterOffPeak: 'usg-sess-tint-tools',
			sepPeak: 'usg-sess-tint-messages',
			sepOffPeak: 'usg-sess-tint-tools',
		};

		/** 面板里的一行（dt 标签 / dd 数值；headline=true 时作为小节标题行） */
		function sessRow(label, value, headline) {
			return el('div', { className: 'usg-sess-row' },
