		/** 锚定定位：面板 fixed 于触发器上方（对齐官方 useAnchoredPosition 的行为） */
		function useAnchoredTop(rootRef, panelRef, open) {
			const [pos, setPos] = react.useState(null);
			react.useEffect(() => {
				if (!open) { setPos(null); return; }
				let alive = true;
				const place = () => {
					if (!alive) return;
					const root = rootRef.current, panel = panelRef.current;
					if (!root || !panel) return;
					const r = root.getBoundingClientRect();
					const pw = panel.offsetWidth, ph = panel.offsetHeight;
					const margin = 12, gap = 8;
					let left = r.left + r.width / 2 - pw / 2;
					left = Math.max(margin, Math.min(left, window.innerWidth - pw - margin));
					let top = r.top - ph - gap;
					if (top < margin) top = Math.min(r.bottom + gap, window.innerHeight - ph - margin);
					setPos({ left: Math.round(left), top: Math.round(top) });
				};
				place();
				window.addEventListener('resize', place);
				window.addEventListener('scroll', place, true);
				return () => {
					alive = false;
					window.removeEventListener('resize', place);
					window.removeEventListener('scroll', place, true);
				};
			}, [open]);
			return pos;
		}

		/** 详情面板：header（本会话花费 + 今日合计）、分时段条、token 明细、模型分布、今日预算 */
		function SessionDetailPanel({ data, s, b, sessionId, fmtMoney, budget }) {
			// 分时段花费（用 recent 中该会话的条目聚合）
			const recents = (s.recent || []).filter((r) => r.sessionId === sessionId);
			const bandAgg = {};
			for (const r of recents) {
				if (!bandAgg[r.band]) bandAgg[r.band] = { cost: 0, calls: 0 };
				bandAgg[r.band].cost += r.cost;
				bandAgg[r.band].calls += 1;
			}
			const bandKeys = Object.keys(bandAgg);
			const bandTotal = bandKeys.reduce((m, k) => m + bandAgg[k].cost, 0);
			// 模型分布
			const modelAgg = {};
			for (const r of recents) {
				const mk = r.modelKey || (typeof r.model === 'string' ? (r.model.indexOf('flash') >= 0 ? 'flash' : r.model.indexOf('pro') >= 0 ? 'pro' : 'other') : 'other');
				if (!modelAgg[mk]) modelAgg[mk] = { calls: 0, cost: 0, name: r.model };
				modelAgg[mk].calls += 1;
				modelAgg[mk].cost += r.cost;
			}
			const tb = todayBucket(s);
			const daily = budget && budget.daily && budget.daily.limit != null ? budget.daily : null;
			const dailyPct = daily && daily.limit > 0 ? Math.min(999, Math.round((daily.spent / daily.limit) * 100)) : null;
			// 官方口径命中率：hit / 输入总量（input 已含缓存命中部分）；input=0 时用 hit+miss 兜底
			const hitRate = b.input > 0 ? Math.round((b.cacheHit / b.input) * 100)
				: (b.cacheHit + b.cacheMiss > 0 ? Math.round((b.cacheHit / (b.cacheHit + b.cacheMiss)) * 100) : null);
			// 分段条：时段占比（无数据则单段预算进度）
			const segments = bandTotal > 0
				? bandKeys.map((k) => ({ key: k, tint: SESS_BAND_TINT[k], width: (bandAgg[k].cost / bandTotal) * 100 }))
				: (dailyPct != null ? [{ key: 'total', tint: null, width: Math.min(100, dailyPct) }] : []);
			return el('div', {
				role: 'dialog',
				'aria-label': T('dock.aria'),
				className: 'usg-sess-panel',
			},
				el('div', { className: 'usg-sess-header' },
					el('span', { className: 'usg-sess-headline' }, T('dock.used')),
					el('span', { className: 'usg-sess-percent' }, fmtMoney(b.cost)),
					tb ? el('span', { className: 'usg-sess-figures' }, T('dock.todayFigures', { v: fmtCostQuick(tb.cost) })) : null,
				),
				el('div', { className: 'usg-sess-bar' },
					segments.filter((x) => x.width > 0).map((seg) =>
						el('div', { key: seg.key, className: 'usg-sess-segment' + (seg.tint ? ' ' + seg.tint : ''), style: { width: seg.width + '%' } }))),
				el('dl', { className: 'usg-sess-rows' },
					sessRow(T('dock.calls'), String(b.calls)),
					sessRow(T('dock.in'), fmtTokens(b.input)),
					sessRow(T('dock.cacheHit'), fmtTokens(b.cacheHit) + (hitRate != null ? ` (${hitRate}%)` : '')),
					sessRow(T('dock.out'), fmtTokens(b.output)),
				),
				bandKeys.length > 0 ? el('div', { className: 'usg-sess-div' }) : null,
				bandKeys.length > 0 ? el('dl', { className: 'usg-sess-rows' },
					sessRow(T('dock.bandCost'), '', true),
					...bandKeys.map((k) => sessRow(
						el('span', { className: 'usg-sess-dt-swatch' },
							el('span', { className: 'usg-sess-swatch' + (SESS_BAND_TINT[k] ? ' ' + SESS_BAND_TINT[k] : ''), 'aria-hidden': true }),
							bandLabel(k)),
						fmtMoney(bandAgg[k].cost) + ' · ' + bandAgg[k].calls)),
				) : null,
				Object.keys(modelAgg).length > 1 ? el('div', { className: 'usg-sess-div' }) : null,
				Object.keys(modelAgg).length > 1 ? el('dl', { className: 'usg-sess-rows' },
					sessRow(T('dock.modelUse'), '', true),
					...Object.keys(modelAgg).map((k) => sessRow(modelLabel(modelAgg[k].name || k), modelAgg[k].calls + ' · ' + fmtMoney(modelAgg[k].cost))),
				) : null,
				el('div', { className: 'usg-sess-div' }),
				el('dl', { className: 'usg-sess-rows' },
					sessRow(T('dock.todayBudget'), dailyPct != null ? dailyPct + '%' : T('dock.budgetNone')),
				),
			);
		}

		function DockReadout(props) {
			useLocaleTick();
			const sessionId = typeof props.sessionId === 'string' && props.sessionId.length > 0
				? props.sessionId
				: (props.session && typeof props.session.id === 'string' ? props.session.id : null);
			const data = useStatsData(sessionId !== null, 10000);
			const s = normalizedStats(data);
			const [open, setOpen] = react.useState(false);
			const rootRef = react.useRef(null);
			const panelRef = react.useRef(null);
			const position = useAnchoredTop(rootRef, panelRef, open && !!s && !!sessionId);
			// Esc / 外点关闭（对齐官方 useDismissOnOutsidePointer）
			react.useEffect(() => {
				if (!open) return;
				const onKey = (e) => { if (e.key === 'Escape') setOpen(false); };
				const onPointer = (e) => {
					const root = rootRef.current, panel = panelRef.current;
					if (root && root.contains(e.target)) return;
					if (panel && panel.contains(e.target)) return;
					setOpen(false);
				};
				document.addEventListener('keydown', onKey);
				document.addEventListener('pointerdown', onPointer, true);
				return () => {
					document.removeEventListener('keydown', onKey);
					document.removeEventListener('pointerdown', onPointer, true);
				};
			}, [open]);
			if (!s || !sessionId) return null;
			const b = s.bySession && s.bySession[sessionId];
			if (!b || b.calls <= 0) return null;
			const budget = data && data.budget ? data.budget : null;
			const daily = budget && budget.daily && budget.daily.limit != null ? budget.daily : null;
			const tb = todayBucket(s);
			// ring：今日预算进度；未设预算时画本会话花费占今日合计的比例；全无则空环
			let ringPct = null;
			if (daily && daily.limit > 0) ringPct = Math.min(100, (daily.spent / daily.limit) * 100);
			else if (tb && tb.cost > 0) ringPct = Math.min(100, (b.cost / tb.cost) * 100);
			const ringCls = ringPct == null ? '' : ringPct >= 100 ? ' usg-sess-fill-over' : ringPct >= 80 ? ' usg-sess-fill-warn' : '';
			const fmtMoney = moneyFormatter((data && data.currency) || 'cny', data && data.config ? data.config.usdCny : DEFAULT_USD_CNY);
			return el('span', { className: 'usg-sess-root', ref: rootRef },
				el('button', {
					type: 'button',
					className: 'usg-sess-trigger',
					'aria-label': T('dock.aria'),
					'aria-haspopup': 'dialog',
					'aria-expanded': open,
					title: T('dock.aria'),
					onClick: () => { setOpen(!open); },
				},
					el('svg', { viewBox: '0 0 14 14', width: '14', height: '14', 'aria-hidden': true },
						el('circle', { className: 'usg-sess-track', cx: '7', cy: '7', r: SESS_RADIUS }),
						el('circle', {
							className: 'usg-sess-fill' + ringCls, cx: '7', cy: '7', r: SESS_RADIUS,
							strokeDasharray: `${SESS_CIRCUMFERENCE * (ringPct || 0) / 100} ${SESS_CIRCUMFERENCE}`,
							transform: 'rotate(-90 7 7)',
						}),
					),
					T('dock.used'),
					el('span', { className: 'usg-sess-cost' }, fmtMoney(b.cost)),
					'· ' + b.calls + ' ' + T('dock.calls'),
					'· ' + T('dock.in') + ' ' + fmtTokens(b.input),
					'· ' + T('dock.out') + ' ' + fmtTokens(b.output),
				),
				open && el('div', { ref: panelRef, className: 'usg-sess-anchor', style: position || { visibility: 'hidden', left: 0, top: 0 } },
					el(SessionDetailPanel, { data, s, b, sessionId, fmtMoney, budget })),
			);
		}

		// ---------- 主界面 · 侧边栏底部卡片（参考设计：Token 用量卡片） ----------
		function cardModel(s, sessionId) {
			if (!s) return null;
			const recents = (s.recent || []).filter((r) => (sessionId ? r.sessionId === sessionId : true));
			if (recents.length > 0) return recents[0].model;
			// 回退：从全量 recent 取最近一次调用的真实模型名（而非硬编码）
			if ((s.recent || []).length > 0) return s.recent[0].model;
			const byModel = s.byModel || {};
			if (byModel.flash && byModel.flash.calls > 0) return 'deepseek-flash';
			if (byModel.pro && byModel.pro.calls > 0) return 'deepseek-v4-pro';
			if (byModel.other && byModel.other.calls > 0) return T('model.other');
			return null;
		}

